css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .casita-wrap{display: grid; grid-template-columns: 1fr auto; gap: 14px; align-items: center;}
.mz .casita-svg{border: 2px solid var(--bosque); border-radius: 10px; padding: 8px; background: #fff;}
.mz .casita-svg svg{width: 100%; height: 200px; display: block;}
.mz .casita-tabla{display: flex; flex-direction: column; gap: 7px;}
.mz .casita-fila{display: flex; align-items: center; gap: 8px; font-size: 12.5px; font-weight: 700;}
.mz .casita-fila svg{width: 24px; height: 24px; flex-shrink: 0;}
.mz .casita-hueco{width: 36px; height: 24px; border: 1.5px solid var(--bosque); border-radius: 5px; flex-shrink: 0;}
.mz .dibujar-grid{display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px;}
.mz .dibujar-caja{display: flex; flex-direction: column; align-items: center; gap: 4px;}
.mz .dibujar-titulo{font-size: 12px; font-weight: 700;}
.mz .dibujar-hueco{width: 100%; height: 110px; border: 1.5px solid var(--bosque); border-radius: 8px;}
.mz .nombrar-fila{display: grid; grid-template-columns: repeat(5, 1fr); gap: 8px;}
.mz .nombrar-caja{display: flex; flex-direction: column; align-items: center; gap: 5px;}
.mz .nombrar-svg{width: 100%; min-height: 50px; display: flex; align-items: center; justify-content: center;}
.mz .nombrar-svg svg{width: 44px; height: 44px;}
.mz .nombrar-linea{width: 100%; border-bottom: 1.5px solid var(--bosque); height: 22px;}
.mz .vf-lista{display: flex; flex-direction: column; gap: 7px;}
.mz .vf-fila{display: grid; grid-template-columns: 1fr auto auto; gap: 12px; align-items: center; font-size: 13px;}
.mz .vf-frase{line-height: 1.4;}
.mz .vf-opcion{display: flex; align-items: center; gap: 4px; font-weight: 700;}
.mz .vf-circ{width: 22px; height: 22px; border: 1.5px solid var(--bosque); border-radius: 50%;}
